import {getRuleDefinitions} from '../utils/messages'
import {clickOn, findAllEl, findEl, isClicked, markAsClicked, printLine, sleep} from './modules'

printLine('Must reload extension for modifications to take effect.')

var isScrollingScriptStarted = false

// task Auto review and collapse autogenerated files
async function onLoad() {
  const rules = await getRuleDefinitions()
  if (!rules.autoCollapseRule?.enabled) return
  if (isScrollingScriptStarted) return
  if (!location.href.match(/https:\/\/github.com/)) return

  isScrollingScriptStarted = true

  printLine('Page Tuner automation is running...')

  rules.autoCollapseRule.specifics.autoGenerateFileNames.forEach((fileName: string) => {
    const withins = findAllEl(`//div[div[h3/a/code[text()[contains(.,'${fileName}')]]]]`)
    for (const within of withins) {
      if (!within) continue
      if (isClicked(within as HTMLElement)) continue

      const expandButton = findEl(
        `div/button[svg[contains(@class,"octicon-chevron")]]`,
        within
      ) as HTMLButtonElement | null

      const reviewedCheckbox = findEl(
        'div/div/button[@aria-label="Not Viewed" or @aria-label="Viewed"]',
        within
      ) as HTMLButtonElement | null

      const slug = findEl(`div/h3/a/code[text()[contains(.,'${fileName}')]]`, within)?.textContent || ''

      if (reviewedCheckbox && reviewedCheckbox.getAttribute('aria-pressed') === 'true') {
        markAsClicked(reviewedCheckbox, slug)
        markAsClicked(within as HTMLElement, slug)
      } else if (reviewedCheckbox && reviewedCheckbox.getAttribute('aria-pressed') === 'false') {
        clickOn(reviewedCheckbox, slug)
        markAsClicked(within as HTMLElement, slug)
      } else {
        clickOn(expandButton, slug)
        markAsClicked(within as HTMLElement, slug)
      }
    }
  })

  isScrollingScriptStarted = false
}

if (location.href.match(/https:\/\/github.com/)) {
  const mainLayout = document.querySelector('div[class*="PageLayout-Content"]')
  if (mainLayout) {
    const observer = new MutationObserver(onLoad)
    observer.observe(mainLayout, {childList: true, subtree: true, characterData: true, attributes: true})
  } else {
    printLine('Could not find div[class*="PageLayout-Content"]')
  }
}

async function exposeCompareAndOpenPullRequestButtons() {
  const rules = await getRuleDefinitions()
  if (!rules.moveCompareButtonRule?.enabled) return
  if (!location.href.match(/https:\/\/github.com/)) return

  // Expose Compare and Open pull request buttons in branch summary
  await sleep(150)

  const branchInfoBar = document.querySelector('[data-testid="branch-info-bar"]')

  const contributeButton = findEl('//button[span/span[text()[contains(.,"Contribute")]]]') as HTMLButtonElement | null

  contributeButton?.click()

  // TODO: for unknown reason elements are findable after some time.
  await sleep(20)

  const compareButtons = findEl('//div[a/span/span[text()[contains(.,"Open pull request")]]] ')

  compareButtons && contributeButton?.parentElement?.appendChild(compareButtons)

  contributeButton?.click()

  contributeButton && (contributeButton.style.display = 'none')
}

exposeCompareAndOpenPullRequestButtons()

// Peakon.com survey answer memory
async function initPeakonAnswerMemory() {
  const rules = await getRuleDefinitions()
  if (!rules.peakonRememberAnswersRule?.enabled) return
  if (!location.href.match(/https:\/\/.*peakon\.com/)) return

  printLine('Peakon answer memory automation is running...')

  const STORAGE_KEY = 'peakon_survey_answers'
  let lastQuestionText = ''

  function getQuestionText(): string | null {
    const questionTitle = document.getElementById('question-item-title')
    return questionTitle?.textContent?.trim() || null
  }

  function getAnswerButtons(): HTMLButtonElement[] {
    const buttons = document.querySelectorAll<HTMLButtonElement>('button[data-scale]')
    return Array.from(buttons)
  }

  function getAllAnswers(): Record<string, string> {
    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      return stored ? JSON.parse(stored) : {}
    } catch {
      return {}
    }
  }

  function saveAnswer(questionText: string, answerValue: string) {
    const answers = getAllAnswers()
    answers[questionText] = answerValue
    localStorage.setItem(STORAGE_KEY, JSON.stringify(answers))
    printLine(`Saved answer for "${questionText}": ${answerValue}`)
  }

  function getSavedAnswer(questionText: string): string | null {
    const answers = getAllAnswers()
    return answers[questionText] || null
  }

  function highlightPreviousAnswer(questionText: string) {
    const savedAnswer = getSavedAnswer(questionText)
    if (!savedAnswer) return

    const buttons = getAnswerButtons()
    const targetButton = buttons.find(btn => btn.getAttribute('data-scale') === savedAnswer)

    if (targetButton) {
      // Add visual indicator
      targetButton.style.outline = '3px solid #4CAF50'
      targetButton.style.outlineOffset = '2px'
      targetButton.style.borderRadius = '4px'
      targetButton.title = `Previous answer: ${savedAnswer}`
    }
  }

  function removeHighlights() {
    const buttons = getAnswerButtons()
    buttons.forEach(btn => {
      btn.style.outline = ''
      btn.style.outlineOffset = ''
      btn.style.borderRadius = ''
      btn.title = ''
    })
  }

  function handleAnswerClick(event: Event) {
    const target = event.target as HTMLElement

    // Check if this click is on or inside a button with data-scale
    const button = target.closest('button[data-scale]') as HTMLButtonElement | null

    if (!button) {
      // Also check for "Change current score" button which opens the scale selector
      const changeScoreBtn = target.closest('button[data-test-id="score"]') as HTMLButtonElement | null
      if (changeScoreBtn) {
        // Wait a bit then re-observe buttons
        setTimeout(() => {
          observeAnswerButtons()
        }, 300)
      }
      return
    }

    const questionText = getQuestionText()
    if (!questionText) return

    const answerValue = button.getAttribute('data-scale')
    if (answerValue) {
      saveAnswer(questionText, answerValue)
    }
  }

  // Watch for aria-pressed changes on buttons (backup method)
  const buttonObserver = new MutationObserver(mutations => {
    mutations.forEach(mutation => {
      if (mutation.type === 'attributes' && mutation.attributeName === 'aria-pressed') {
        const button = mutation.target as HTMLButtonElement
        const ariaPressed = button.getAttribute('aria-pressed')

        if (button.hasAttribute('data-scale') && ariaPressed === 'true') {
          const questionText = getQuestionText()
          if (questionText) {
            const answerValue = button.getAttribute('data-scale')
            if (answerValue) {
              saveAnswer(questionText, answerValue)
            }
          }
        }
      }
    })
  })

  const observedButtons = new WeakSet<HTMLButtonElement>()

  function observeAnswerButtons() {
    const buttons = getAnswerButtons()
    buttons.forEach(btn => {
      // Only observe if we haven't already observed this button
      if (!observedButtons.has(btn)) {
        buttonObserver.observe(btn, {attributes: true, attributeFilter: ['aria-pressed']})
        observedButtons.add(btn)
      }
    })
  }

  function checkAndHighlightAnswer() {
    const questionText = getQuestionText()
    if (!questionText || questionText === lastQuestionText) {
      // Even if question hasn't changed, re-observe buttons in case they were recreated
      setTimeout(() => {
        const buttons = getAnswerButtons()
        if (buttons.length > 0) {
          observeAnswerButtons()
        }
      }, 500)
      return
    }

    lastQuestionText = questionText
    removeHighlights()

    // Wait a bit for buttons to be fully rendered
    setTimeout(() => {
      highlightPreviousAnswer(questionText)
      observeAnswerButtons() // Re-observe buttons when question changes
    }, 100)

    // Also re-observe after a longer delay in case buttons load slowly
    setTimeout(() => {
      observeAnswerButtons()
    }, 500)
  }

  // Attach click handlers immediately (they work globally)
  document.addEventListener('click', handleAnswerClick, true)

  // Function to setup observers when container is found
  function setupQuestionObservers() {
    const questionContainer = document.querySelector('[data-test-id="question-container"]')
    if (!questionContainer) {
      return false
    }

    const observer = new MutationObserver(() => {
      checkAndHighlightAnswer()
    })
    observer.observe(questionContainer, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true
    })

    // Initial check
    checkAndHighlightAnswer()

    // Also listen on the button container directly if it exists
    const buttonContainer = document.querySelector('.fvysv[role="group"]')
    if (buttonContainer) {
      buttonContainer.addEventListener('click', handleAnswerClick, true)
    }

    // Initial observation of buttons
    const buttons = getAnswerButtons()
    if (buttons.length > 0) {
      observeAnswerButtons()
    }

    return true
  }

  // Try to setup immediately
  if (!setupQuestionObservers()) {
    // If not found, wait for it to appear
    // Watch the entire document for the container to appear
    const documentObserver = new MutationObserver(() => {
      if (setupQuestionObservers()) {
        documentObserver.disconnect()
      }
    })

    documentObserver.observe(document.body, {
      childList: true,
      subtree: true
    })

    // Also try after a delay
    setTimeout(() => {
      if (setupQuestionObservers()) {
        documentObserver.disconnect()
      }
    }, 1000)
  }
}

if (location.href.match(/https:\/\/.*peakon\.com/)) {
  initPeakonAnswerMemory()
}

// Mark file as viewed via Shift+Space
async function initMarkFileAsViewed() {
  const rules = await getRuleDefinitions()
  if (!rules.markFileAsViewedRule?.enabled) return
  if (!location.href.match(/https:\/\/github.com/)) return

  printLine('Mark file as viewed automation is running...')

  let currentHintBtn: HTMLButtonElement | null = null

  function setHint(viewedBtn: HTMLButtonElement | null) {
    if (viewedBtn === currentHintBtn) return

    if (currentHintBtn) {
      currentHintBtn.querySelector('.pt-shortcut-hint')?.remove()
      currentHintBtn = null
    }

    if (viewedBtn) {
      const label = viewedBtn.querySelector('[data-component="text"]')
      if (label) {
        const hint = document.createElement('span')
        hint.className = 'pt-shortcut-hint'
        hint.textContent = ' (shift+space)'
        hint.style.cssText = 'font-size:10px;opacity:0.6;font-weight:normal;'
        label.appendChild(hint)
        currentHintBtn = viewedBtn
      }
    }
  }

  document.addEventListener('mouseover', (e: MouseEvent) => {
    const diffFileContainer = (e.target as HTMLElement).closest('[id^="diff-"]')
    const viewedBtn = diffFileContainer?.querySelector<HTMLButtonElement>('button[aria-label="Not Viewed"]') ?? null
    setHint(viewedBtn)
  })

  document.addEventListener('keydown', (e: KeyboardEvent) => {
    if (!e.shiftKey || e.key !== ' ') return
    if (!currentHintBtn) return

    e.preventDefault()
    currentHintBtn.click()
    printLine(`Marked file as viewed via Shift+Space`)
  })
}

if (location.href.match(/https:\/\/github.com/)) {
  initMarkFileAsViewed()
}

// Go to line in editor
async function initGoToLineInEditor() {
  const rules = await getRuleDefinitions()
  if (!rules.goToLineInEditorRule?.enabled) return
  if (!location.href.match(/https:\/\/github.com/)) return

  printLine('Go to line in editor automation is running...')

  const EDITOR_SCHEME = 'cursor'
  const INJECTED_CLASS = 'pt-goto-editor-btn'
  const repoMappings: Record<string, string> = rules.goToLineInEditorRule?.specifics?.repoMappings || {}

  function getOrgRepo(): string | null {
    const match = location.pathname.match(/^\/([^/]+\/[^/]+)/)
    return match ? match[1] : null
  }

  function getLocalRoot(): string | null {
    const orgRepo = getOrgRepo()
    if (!orgRepo) return null
    return repoMappings[orgRepo] || null
  }

  function getFilePathForDiff(diffContainer: Element): string | null {
    const expandBtn = diffContainer.querySelector<HTMLButtonElement>('button[data-file-path]')
    if (expandBtn) return expandBtn.getAttribute('data-file-path')

    const codeEl = diffContainer.querySelector<HTMLElement>('.DiffFileHeader-module__file-name__VVXpg a code')
    if (codeEl) {
      return codeEl.textContent?.replace(/\u200e/g, '').trim() || null
    }

    return null
  }

  function createEditorButton(addCommentBtn: HTMLButtonElement, filePath: string, lineNumber: number): HTMLButtonElement {
    const btn = addCommentBtn.cloneNode(false) as HTMLButtonElement
    btn.classList.add(INJECTED_CLASS)
    btn.removeAttribute('data-add-comment-button')
    btn.setAttribute('aria-label', `Open ${filePath}:${lineNumber} in editor`)

    btn.innerHTML = `<svg aria-hidden="true" focusable="false" class="octicon" viewBox="85 89 343 334" width="14" height="14" fill="currentColor" display="inline-block" overflow="visible" style="vertical-align:text-bottom;"><path d="M255.428 423l148.991-83.5L255.428 256l-148.99 83.5z" opacity=".6"/><path d="M404.419 339.5v-167L255.428 89v167z" opacity=".3"/><path d="M255.428 89l-148.99 83.5v167l148.99-83.5z" opacity=".5"/><path d="M404.419 172.5L255.428 423V256z" opacity=".85"/><path d="M404.419 172.5L255.428 256l-148.99-83.5z"/></svg>`

    btn.addEventListener('click', e => {
      e.preventDefault()
      e.stopPropagation()
      const localRoot = getLocalRoot()
      if (!localRoot) {
        alert(`No local path configured for "${getOrgRepo()}". Add it in the Page Tuner popup under "Go to line in editor".`)
        return
      }
      const cleanPath = filePath.replace(/^\/+/, '')
      const root = localRoot.replace(/\/+$/, '')
      window.location.href = `${EDITOR_SCHEME}://file/${root}/${cleanPath}:${lineNumber}`
    })

    return btn
  }

  function injectButtons() {
    const addCommentButtons = document.querySelectorAll<HTMLButtonElement>('button[data-add-comment-button="true"]')

    for (const addBtn of Array.from(addCommentButtons)) {
      const container = addBtn.closest('div.d-flex.flex-row') as HTMLElement | null
      if (!container) continue
      if (container.querySelector(`.${INJECTED_CLASS}`)) continue

      const lineCell = addBtn.closest('td[data-line-number]') as HTMLElement | null
      const lineNumber = lineCell?.getAttribute('data-line-number')
      if (!lineNumber) continue

      const diffContainer = addBtn.closest('[id^="diff-"]')
      if (!diffContainer) continue

      const filePath = getFilePathForDiff(diffContainer)
      if (!filePath) continue

      const editorBtn = createEditorButton(addBtn, filePath, parseInt(lineNumber, 10))
      container.appendChild(editorBtn)
    }
  }

  const pageContent = document.querySelector('div[class*="PageLayout-Content"]')
  if (pageContent) {
    const observer = new MutationObserver(injectButtons)
    observer.observe(pageContent, {childList: true, subtree: true})
  }

  injectButtons()
}

if (location.href.match(/https:\/\/github.com/)) {
  initGoToLineInEditor()
}

